# Public API (cm:*)
  @api cm:setContext(newTake)  @ 422-427
      @contract  setContext(nil) clears take+track; setContext(take) derives track via GetMediaItemTrack  @ 420
      @contract  refreshes all persisted caches (transient resets to {}) and fires configChanged {}  @ 421
  @api cm:clearTake()  @ 429-434
  @api cm:boundTake()  @ 437
      @contract  bound take pointer; nil when context is cleared (take/track tiers resolve off empty)  @ 436
  @api cm:boundTrack()  @ 440
      @contract  bound track pointer; nil when context is cleared (track tier resolves off empty)  @ 439
  @api cm:setTrack(newTrack)  @ 442-447
  @api cm:pollUndo()  @ 450
      @contract  delegates to the engine watcher; cm's watch group reloads tiers and fires configChanged  @ 449
  @api cm:isDeclared(key)  @ 487
      @contract  non-raising existence test against the schema; true iff key is declared  @ 486
  @api cm:get(key, opts)  @ 494-501
      -- pick is orthogonal to the merge mode: it indexes whatever that mode resolved, so only the
      -- one entry crosses the boundary. A nil pick is indistinguishable from none (see the spec).
  @api cm:getAt(level, key)  @ 504-513
      @contract  reads single tier only (no merge, no defaults); key nil → whole-cache clone  @ 503
  @api cm:valueFor(handle, scope, key)  @ 516-523
      @contract  single-tier value for a foreign take/track handle (ps:getAt); no merge or defaults  @ 515
  @api cm:defaultFor(key)  @ 526-529
      @contract  deep-copy of the schema default for key (no tiers, no merge); raises on unknown key  @ 525
  -- Writing
  @api cm:set(level, key, value)  @ 534-544
      @contract  deep-copies value into tier cache, persists, fires targeted configChanged  @ 533
  @api cm:remove(level, key)  @ 547-558
      @contract  removes key from named tier; no-op (no signal) if that tier's cache is unloaded  @ 546
  @api cm:assign(level, updates)  @ 561-575
      @contract  validates all keys before any write (all-or-nothing); REMOVE deletes; fires signal  @ 560

